1	import { useEffect, useMemo, useState } from 'react';
2	import {
3	  Loader2,
4	  Save,
5	  ArrowLeft,
6	  CheckSquare,
7	  XSquare,
8	  Search,
9	  Layers,
10	} from 'lucide-react';
11	import { Button } from '@/shared/ui/button';
12	import { Checkbox } from '@/shared/ui/checkbox';
13	import { Input } from '@/shared/ui/input';
14	import {
15	  Select,
16	  SelectContent,
17	  SelectItem,
18	  SelectTrigger,
19	  SelectValue,
20	} from '@/shared/ui/select';
21	import { supabase } from '@/integrations/supabase/client';
22	import { toast } from '@/shared/hooks/use-toast';
23	import { handleError } from '@/shared/lib/error-handler';
24	import { useSetores } from '../model/useSetores';
25	import { SetorManager } from './SetorManager';
26	import {
27	  ProdutoSetorUnidadeDialog,
28	  type ProdutoEdit,
29	} from './ProdutoSetorUnidadeDialog';
30	
31	/**
32	 * Matrix de Visibilidade Produto × Loja.
33	 *
34	 * Admin-only. Carrega produtos ativos de `produtos_master` e lojas ativas,
35	 * cruza com `produto_loja_visibility` e renderiza um grid de checkboxes.
36	 * Controla quais produtos aparecem na aba Contagem de cada loja.
37	 *
38	 * Recuperado do commit 41a96c4 (perdido no refactor FSD). A view
39	 * `vw_produtos_estoque_lojas` que alimenta a contagem JÁ faz INNER JOIN
40	 * com esta tabela, então as mudanças refletem direto na contagem.
41	 */
42	
43	interface ProductVisibilityMatrixProps {
44	  onBack: () => void;
45	}
46	
47	interface Produto {
48	  id: number;
49	  nome: string;
50	  setor: string;
51	  codigo_interno: number | null;
52	  unidade_medida: string | null;
53	}
54	
55	interface Loja {
56	  id: number;
57	  nome: string;
58	}
59	
60	const visKey = (prodId: number, lojaId: number) => `${prodId}_${lojaId}`;
61	
62	const setorEmoji = (nome: string): string => {
63	  const n = (nome || '').toLowerCase();
64	  if (n.includes('camara fria') || n.includes('câmara fria')) return '❄️';
65	  if (n === 'insumos' || n.includes('estoque insumos')) return '🥄';
66	  if (n === 'mercearia') return '🛒';
67	  if (n === 'embalagens') return '📦';
68	  if (n === 'limpeza') return '🧼';
69	  if (n === 'natal') return '🎅';
70	  if (n === 'todos') return '🌎';
71	  if (n === 'sem setor') return '❓';
72	  return '🏷️';
73	};
74	
75	export function ProductVisibilityMatrix({
76	  onBack,
77	}: ProductVisibilityMatrixProps) {
78	  const [loading, setLoading] = useState(false);
79	  const [saving, setSaving] = useState(false);
80	  const [allProducts, setAllProducts] = useState<Produto[]>([]);
81	  const [lojas, setLojas] = useState<Loja[]>([]);
82	  const [officialSetoresList, setOfficialSetoresList] = useState<string[]>([]);
83	  const [visibility, setVisibility] = useState<Record<string, boolean>>({});
84	  const [initialVisibility, setInitialVisibility] = useState<
85	    Record<string, boolean>
86	  >({});
87	  const [searchTerm, setSearchTerm] = useState('');
88	  const [setorSelecionado, setSetorSelecionado] = useState('Todos');
89	
90	  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());
91	  const [setorDestino, setSetorDestino] = useState('');
92	  const [showSetorManager, setShowSetorManager] = useState(false);
93	  const [editandoProduto, setEditandoProduto] = useState<ProdutoEdit | null>(
94	    null,
95	  );
96	  const [movendoMassa, setMovendoMassa] = useState(false);
97	  const { setores: setoresCanonicos, moverItensSelecionados } = useSetores();
98	
99	  useEffect(() => {
100	    loadData();
101	  }, []);
102	
103	  const reloadSetores = async () => {
104	    const { data, error } = await supabase
105	      .from('setores')
106	      .select('nome, ativo')
107	      .eq('ativo', true)
108	      .order('nome');
109	    if (!error && data) {
110	      const officialSetores = (data as any[])
111	        .map((s: any) => s.nome as string)
112	        .filter((n: string) => !!n && n.trim() !== '');
113	      setOfficialSetoresList(officialSetores);
114	    }
115	  };
116	
117	  const loadData = async () => {
118	    setLoading(true);
119	    try {
120	      // 1. Setores oficiais (fonte da verdade — mesma tabela usada na Contagem)
121	      const { data: setoresData, error: setoresError } = await supabase
122	        .from('setores')
123	        .select('nome, ativo')
124	        .eq('ativo', true)
125	        .order('nome');
126	      if (setoresError) throw setoresError;
127	      const officialSetores = (setoresData || [])
128	        .map((s: any) => s.nome as string)
129	        .filter((n: string) => !!n && n.trim() !== '');
130	      // Map normalizado (UPPERCASE + trim) → nome canônico para match case-insensitive
131	      const officialMap = new Map<string, string>();
132	      officialSetores.forEach((n) => {
133	        officialMap.set(n.trim().toUpperCase(), n);
134	      });
135	
136	      // 2. Produtos ativos
137	      const { data: productsData, error: productsError } = await supabase
138	        .from('produtos_master')
139	        .select('id, nome, setor, codigo_interno, ativo, unidade_medida')
140	        .eq('ativo', true)
141	        .order('nome');
142	      if (productsError) throw productsError;
143	
144	      // 3. Lojas ativas
145	      const { data: lojasData, error: lojasError } = await supabase
146	        .from('lojas')
147	        .select('id, nome')
148	        .or('ativo.eq.true,ativo.is.null')
149	        .order('id');
150	      if (lojasError) throw lojasError;
151	
152	      // 4. Visibilidade (paginado — pode ultrapassar 1000 linhas)
153	      const visAll: {
154	        produto_master_id: number;
155	        loja_id: number;
156	        ativo: boolean;
157	      }[] = [];
158	      let offset = 0;
159	      const PAGE = 1000;
160	      while (true) {
161	        const { data: batch, error: batchErr } = await supabase
162	          .from('produto_loja_visibility' as any)
163	          .select('produto_master_id, loja_id, ativo')
164	          .range(offset, offset + PAGE - 1);
165	        if (batchErr) throw batchErr;
166	        if (!batch || batch.length === 0) break;
167	        visAll.push(...(batch as any));
168	        if (batch.length < PAGE) break;
169	        offset += PAGE;
170	      }
171	
172	      // Normaliza setor de cada produto pro nome canônico (case-insensitive).
173	      // Produtos com setor inválido (NULL, "Todos", etc) recebem 'SEM SETOR' em vez de serem descartados.
174	      const prods: Produto[] = (productsData || []).map((p: any) => {
175	        const raw = (p.setor || '').trim();
176	        const canonical = raw ? officialMap.get(raw.toUpperCase()) : undefined;
177	        return {
178	          id: p.id,
179	          nome: p.nome,
180	          setor: canonical ?? 'SEM SETOR',
181	          codigo_interno: p.codigo_interno,
182	          unidade_medida: p.unidade_medida,
183	        };
184	      });
185	
186	      setAllProducts(prods);
187	      setOfficialSetoresList(officialSetores);
188	      setLojas(
189	        (lojasData || []).map((l: any) => ({ id: l.id, nome: l.nome })),
190	      );
191	
192	      const visMap: Record<string, boolean> = {};
193	      visAll.forEach((v) => {
194	        visMap[visKey(v.produto_master_id, v.loja_id)] = v.ativo;
195	      });
196	      setVisibility(visMap);
197	      setInitialVisibility({ ...visMap });
198	    } catch (error) {
199	      handleError(error, {
200	        domain: 'produtos',
201	        operation: 'loadVisibilityMatrix',
202	        showToast: false,
203	      });
204	      toast({
205	        title: 'Erro ao carregar matrix de visibilidade',
206	        variant: 'destructive',
207	      });
208	    } finally {
209	      setLoading(false);
210	    }
211	  };
212	
213	  const setores = useMemo(() => {
214	    const hasOrfaos = allProducts.some((p) => p.setor === 'SEM SETOR');
215	    return [
216	      'Todos',
217	      ...(hasOrfaos ? ['SEM SETOR'] : []),
218	      ...officialSetoresList,
219	    ];
220	  }, [officialSetoresList, allProducts]);
221	
222	  const filteredProducts = useMemo(() => {
223	    const term = searchTerm.trim().toLowerCase();
224	    return allProducts.filter((p) => {
225	      const matchesSearch =
226	        !term ||
227	        p.nome.toLowerCase().includes(term) ||
228	        (p.codigo_interno?.toString() || '').includes(term);
229	      const matchesSetor =
230	        setorSelecionado === 'Todos' || p.setor === setorSelecionado;
231	      return matchesSearch && matchesSetor;
232	    });
233	  }, [allProducts, searchTerm, setorSelecionado]);
234	
235	  const groupedProducts = useMemo(() => {
236	    const groups: Record<string, Produto[]> = {};
237	    filteredProducts.forEach((p) => {
238	      if (!groups[p.setor]) groups[p.setor] = [];
239	      groups[p.setor].push(p);
240	    });
241	    return groups;
242	  }, [filteredProducts]);
243	
244	  const toggleCell = (prodId: number, lojaId: number) => {
245	    const key = visKey(prodId, lojaId);
246	    setVisibility((prev) => ({ ...prev, [key]: !prev[key] }));
247	  };
248	
249	  const selectAllForStore = (lojaId: number) => {
250	    setVisibility((prev) => {
251	      const next = { ...prev };
252	      filteredProducts.forEach((p) => {
253	        next[visKey(p.id, lojaId)] = true;
254	      });
255	      return next;
256	    });
257	  };
258	
259	  const deselectAllForStore = (lojaId: number) => {
260	    setVisibility((prev) => {
261	      const next = { ...prev };
262	      filteredProducts.forEach((p) => {
263	        next[visKey(p.id, lojaId)] = false;
264	      });
265	      return next;
266	    });
267	  };
268	
269	  const selectSectorForStore = (setor: string, lojaId: number) => {
270	    setVisibility((prev) => {
271	      const next = { ...prev };
272	      filteredProducts
273	        .filter((p) => p.setor === setor)
274	        .forEach((p) => {
275	          next[visKey(p.id, lojaId)] = true;
276	        });
277	      return next;
278	    });
279	  };
280	
281	  const deselectSectorForStore = (setor: string, lojaId: number) => {
282	    setVisibility((prev) => {
283	      const next = { ...prev };
284	      filteredProducts
285	        .filter((p) => p.setor === setor)
286	        .forEach((p) => {
287	          next[visKey(p.id, lojaId)] = false;
288	        });
289	      return next;
290	    });
291	  };
292	
293	  const hasChanges = useMemo(
294	    () => JSON.stringify(visibility) !== JSON.stringify(initialVisibility),
295	    [visibility, initialVisibility],
296	  );
297	
298	  const changedCount = useMemo(() => {
299	    const keys = new Set([
300	      ...Object.keys(visibility),
301	      ...Object.keys(initialVisibility),
302	    ]);
303	    let count = 0;
304	    keys.forEach((k) => {
305	      if ((visibility[k] ?? false) !== (initialVisibility[k] ?? false))
306	        count++;
307	    });
308	    return count;
309	  }, [visibility, initialVisibility]);
310	
311	  const handleSave = async () => {
312	    setSaving(true);
313	    try {
314	      const keys = new Set([
315	        ...Object.keys(visibility),
316	        ...Object.keys(initialVisibility),
317	      ]);
318	      const upserts: {
319	        produto_master_id: number;
320	        loja_id: number;
321	        ativo: boolean;
322	      }[] = [];
323	
324	      keys.forEach((k) => {
325	        const newVal = visibility[k] ?? false;
326	        const oldVal = initialVisibility[k] ?? false;
327	        if (newVal !== oldVal) {
328	          const [prodId, lojaId] = k.split('_').map(Number);
329	          upserts.push({
330	            produto_master_id: prodId,
331	            loja_id: lojaId,
332	            ativo: newVal,
333	          });
334	        }
335	      });
336	
337	      if (upserts.length === 0) {
338	        toast({ title: 'Nenhuma alteração para salvar' });
339	        setSaving(false);
340	        return;
341	      }
342	
343	      // Chunking para lotes grandes
344	      for (let i = 0; i < upserts.length; i += 100) {
345	        const batch = upserts.slice(i, i + 100);
346	        const { error } = await supabase
347	          .from('produto_loja_visibility' as any)
348	          .upsert(batch as any, { onConflict: 'produto_master_id,loja_id' });
349	        if (error) throw error;
350	      }
351	
352	      setInitialVisibility({ ...visibility });
353	      toast({ title: `${upserts.length} alterações salvas com sucesso!` });
354	    } catch (error) {
355	      handleError(error, {
356	        domain: 'produtos',
357	        operation: 'saveVisibilityMatrix',
358	        showToast: false,
359	      });
360	      toast({
361	        title: 'Erro ao salvar alterações',
362	        variant: 'destructive',
363	      });
364	    } finally {
365	      setSaving(false);
366	    }
367	  };
368	
369	  const handleMoverMassa = async () => {
370	    if (selectedIds.size === 0 || !setorDestino) return;
371	    setMovendoMassa(true);
372	    const r = await moverItensSelecionados([...selectedIds], setorDestino);
373	    if (r.ok) {
374	      toast({
375	        title: `${r.movidos ?? 0} produtos movidos para ${setorDestino}`,
376	      });
377	      setAllProducts((prev) =>
378	        prev.map((p) =>
379	          selectedIds.has(p.id) ? { ...p, setor: setorDestino } : p,
380	        ),
381	      );
382	      setSelectedIds(new Set());
383	      setSetorDestino('');
384	    } else {
385	      toast({
386	        title: 'Erro ao mover produtos',
387	        description: r.error,
388	        variant: 'destructive',
389	      });
390	    }
391	    setMovendoMassa(false);
392	  };
393	
394	  return (
395	    <div className="space-y-4">
396	      {/* Header / Controls */}
397	      <div className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 p-4 rounded-3xl shadow-sm">
398	        <div className="flex flex-col xl:flex-row gap-4 justify-between items-start xl:items-center">
399	          <div className="flex items-center gap-3">
400	            <Button
401	              data-mia-action="on-back"
402	              variant="ghost"
403	              onClick={onBack}
404	              className="gap-2 text-[#57715B] hover:bg-[#57715B]/10 rounded-xl"
405	            >
406	              <ArrowLeft className="h-4 w-4" /> Voltar
407	            </Button>
408	            <div>
409	              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
410	                Gerenciar Visibilidade por Loja
411	              </h2>
412	              <p className="text-xs text-muted-foreground">
413	                {filteredProducts.length} produtos · {lojas.length} lojas
414	                {changedCount > 0 && (
415	                  <span className="ml-2 text-amber-600 font-medium">
416	                    ({changedCount} alterações não salvas)
417	                  </span>
418	                )}
419	              </p>
420	            </div>
421	          </div>
422	
423	          <div className="flex flex-col sm:flex-row gap-2 w-full xl:w-auto">
424	            <div className="relative flex-1 sm:w-[260px]">
425	              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
426	              <Input
427	                data-mia-field="search_term"
428	                placeholder="Buscar por nome ou código..."
429	                value={searchTerm}
430	                onChange={(e) => setSearchTerm(e.target.value)}
431	                className="pl-9 bg-white/80 dark:bg-zinc-900/80 border-[#57715B]/20 rounded-xl h-10"
432	              />
433	            </div>
434	            <Select value={setorSelecionado} onValueChange={setSetorSelecionado}>
435	              <SelectTrigger
436	                data-mia-filter="setor_selecionado"
437	                className="w-full sm:w-[200px] bg-white/80 dark:bg-zinc-900/80 border-[#57715B]/20 rounded-xl h-10"
438	              >
439	                <SelectValue />
440	              </SelectTrigger>
441	              <SelectContent>
442	                {setores.map((s) => (
443	                  <SelectItem key={s} value={s}>
444	                    <span className="mr-2">{setorEmoji(s)}</span>
445	                    {s}
446	                  </SelectItem>
447	                ))}
448	              </SelectContent>
449	            </Select>
450	            <Button
451	              data-mia-action="abrir_gerir_setores"
452	              onClick={() => setShowSetorManager(true)}
453	              className="bg-white/60 dark:bg-black/20 border border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 rounded-xl h-10 gap-2 shrink-0"
454	            >
455	              <Layers className="h-4 w-4" />
456	              <span className="hidden sm:inline">Gerenciar Setores</span>
457	            </Button>
458	          </div>
459	        </div>
460	      </div>
461	
462	      {/* Matrix */}
463	      {loading ? (
464	        <div className="flex items-center justify-center py-16">
465	          <div className="flex flex-col items-center gap-3">
466	            <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
467	            <p className="text-[#57715B] font-medium">
468	              Carregando matrix de visibilidade...
469	            </p>
470	          </div>
471	        </div>
472	      ) : filteredProducts.length === 0 ? (
473	        <div className="text-center py-12 text-muted-foreground bg-white/60 dark:bg-zinc-900/60 rounded-3xl border border-[#57715B]/10">
474	          <p className="text-lg font-medium">Nenhum produto encontrado</p>
475	          <p className="text-sm mt-1">Ajuste os filtros para ver produtos.</p>
476	        </div>
477	      ) : (
478	        <div className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-3xl shadow-sm overflow-hidden">
479	          <div className="overflow-auto max-h-[calc(100vh-300px)]">
480	            <table className="w-full text-sm border-separate border-spacing-0">
481	              <thead>
482	                <tr>
483	                  <th
484	                    className="sticky left-0 bg-white dark:bg-zinc-900 text-left p-3 font-bold text-[#57715B] dark:text-[#E6DCCF] min-w-[280px] border-b border-[#57715B]/10"
485	                    style={{ top: 0, zIndex: 30 }}
486	                  >
487	                    Produto
488	                  </th>
489	                  {lojas.map((loja) => (
490	                    <th
491	                      key={loja.id}
492	                      className="p-3 text-center min-w-[120px] bg-white dark:bg-zinc-900 border-b border-[#57715B]/10 sticky"
493	                      style={{ top: 0, zIndex: 20 }}
494	                    >
495	                      <div className="flex flex-col items-center gap-2">
496	                        <span className="font-bold text-xs text-[#57715B] dark:text-[#E6DCCF] whitespace-nowrap">
497	                          {loja.nome.replace('Momma ', '')}
498	                        </span>
499	                        <div className="flex items-center gap-1">
500	                          <button
501	                            data-mia-skip
502	                            onClick={() => selectAllForStore(loja.id)}
503	                            className="p-1 rounded hover:bg-green-100 dark:hover:bg-green-900/30 text-green-600 dark:text-green-400 transition-colors"
504	                            title={`Marcar todos em ${loja.nome}`}
505	                          >
506	                            <CheckSquare className="h-3.5 w-3.5" />
507	                          </button>
508	                          <button
509	                            data-mia-skip
510	                            onClick={() => deselectAllForStore(loja.id)}
511	                            className="p-1 rounded hover:bg-red-100 dark:hover:bg-red-900/30 text-red-500 dark:text-red-400 transition-colors"
512	                            title={`Desmarcar todos em ${loja.nome}`}
513	                          >
514	                            <XSquare className="h-3.5 w-3.5" />
515	                          </button>
516	                        </div>
517	                      </div>
518	                    </th>
519	                  ))}
520	                </tr>
521	              </thead>
522	              <tbody>
523	                {Object.entries(groupedProducts)
524	                  .sort(([a], [b]) => {
525	                    if (a === 'SEM SETOR') return -1;
526	                    if (b === 'SEM SETOR') return 1;
527	                    return a.localeCompare(b, 'pt-BR');
528	                  })
529	                  .map(([setor, prods]) => (
530	                    <>
531	                      <tr
532	                        key={`setor-${setor}`}
533	                        className="bg-[#57715B]/5 dark:bg-[#57715B]/10"
534	                      >
535	                        <td
536	                          className="sticky left-0 p-2 px-3 bg-[#f8f9fa] dark:bg-[#18181b] border-y border-[#57715B]/10"
537	                          style={{ zIndex: 15 }}
538	                        >
539	                          <div className="flex items-center gap-2">
540	                            <Checkbox
541	                              checked={
542	                                prods.length > 0 &&
543	                                prods.every((p) => selectedIds.has(p.id))
544	                              }
545	                              onCheckedChange={(checked) => {
546	                                setSelectedIds((prev) => {
547	                                  const next = new Set(prev);
548	                                  prods.forEach((p) => {
549	                                    if (checked) {
550	                                      next.add(p.id);
551	                                    } else {
552	                                      next.delete(p.id);
553	                                    }
554	                                  });
555	                                  return next;
556	                                });
557	                              }}
558	                              aria-label={`Selecionar todos de ${setor}`}
559	                              className="h-4 w-4 rounded border-[#57715B]/30 data-[state=checked]:bg-[#57715B] data-[state=checked]:border-[#57715B] shrink-0"
560	                            />
561	                            <span className="font-bold text-xs uppercase tracking-wider text-[#57715B] dark:text-[#E6DCCF]">
562	                              {setorEmoji(setor)} {setor} ({prods.length})
563	                            </span>
564	                          </div>
565	                        </td>
566	                        {lojas.map((loja) => (
567	                          <td
568	                            key={loja.id}
569	                            className="p-1 text-center bg-[#f8f9fa] dark:bg-[#18181b] border-y border-[#57715B]/10"
570	                          >
571	                            <div className="flex items-center justify-center gap-1">
572	                              <button
573	                                data-mia-skip
574	                                onClick={() =>
575	                                  selectSectorForStore(setor, loja.id)
